module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    assign out = (sel == 2'b00) ? in[0] :
                (sel == 2'b01) ? in[1] :
                (sel == 2'b10) ? in[2] :
                (sel == 2'b11) ? in[3] : 1'b0;
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] a_eq_b;
    wire [3:0] x, y;

    assign x = a & b;
    assign y = (~a) & (~b);

    assign a_eq_b = x ^ y;

    assign equal = &a_eq_b;
endmodule

