always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 3'b000;
        enable <= 1'b0;
        light <= 3'b111;
    end
    else begin
        case (state)
            3'b000: begin
                if (enable) state <= 3'b110;
                else end
            end
            3'b110: begin
                state <= 3'b101;
            end
            3'b101: begin
                state <= 3'b011;
            end
            3'b011: begin
                state <= 3'b001;
            end
            3'b001: begin
                state <= 3'b111;
            end
            default: begin
                state <= 3'b110;
                enable <= 1'b0;
            end
        endcase
    end
end

reg [1:0] state;
reg S_DFFE_PPOP, S_DFFE_PPOP_;
reg D, E, R;
reg [1:0] St;
reg now_state;
reg previous [1:0], present [1:0];
reg [1:0] next_state;
reg Q, next_Q;
reg s0;

always @(*) begin
    D = ((* coin_inserted) & ((* now_state == 2'd1) | (* now_state == 2'd0) | (* now_state == 2'd3) | (* now_state == 2'd2)));
    E = (item_selected) & (* now_state == 2'd0) & Q;
    R = (reset) & (* now_state == 2'd0) & Q;
    if(E) next_Q <= 'd0;
    else if(R) next_Q <= 'd1;
    else if(D) next_Q <= *next_state;
    else next_Q <= Q;
end

always @(*) begin
    if((* now_state == 2'd0) & (* now_state == 2'd1)) next_state = 2'd1;
    else if((* now_state == 2'd2) & item_selected) next_state = 2'd3;
    else if((* now_state == 2'd3) & coin_inserted) next_state = 2'd0;
    else next_state = *now_state;
end

always @(*) begin
    now_state <= *next_state;
    demux = {(* now_state & Q) & *(item_selected == 0) & (S_DFFE_PPOP == 0), *trasel};
    if(now_state == 2'd2) demux = *not*(now_state & *trasel & *(S_DFFE_PPOP == 1) | (*S_DFFE_PPOP == 0) | (*S_DFFE_PPOP == 1));
end

always @(*) begin
    s0 = now_state & coin_inserted;
    if(s0 & now_state == 0) s0 = 2'd1;
    else if(now_state == 1) s0 = 2'd0;
    else if(now_state) s0 = 2'd2;
    else s0 = 2'd3;    
end

always @(*) begin
    St = s0 | now_state;
end

always @(*) begin
    if(reset) state = 2'd0;
    else state = St;
end

always @(*) begin
    D = item_selected & (* now_state == 2'd2) & Q;
    E = reset & (status == 2'd2) & Q;
    R = 0;
    next_Q = Q;
    if(D) next_Q <= 2'd1;
    else if(E) next_Q <= 2'd0;
end

always @(*) begin
    if(Q) present <= 9'd1;
    else present <= 9'd0;
end

always @(*) begin
    if(now_state == 2'd0) if(reset) next_state <= 2'd0;
    else if(E) next_state <= 2'd0;
    else if(R) next_state <= 2'd1;
end

always @(*) begin
    next_state = *when*;
    if(now_state == 2'd0) if(reset) next_state <= 2'd0;
    else if(E) next_state <= 2'd0;
    else if(R) next_state <= 2'd1;
    else next_state <= now_state;
end

assign state = next_state;

