module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    wire [5:0] w0, w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12, w13, w14, w15, w16, w17, w18, w19, w20, w21, w22, w23;

    assign w0 = 16'h0000; // w0 = 0
    assign w1 = in_0 >> 1; // shift right by 1
    assign w2 = w1 >> 1;
    assign w3 = w2 >> 1;
    assign w4 = w3 >> 1;
    assign w5 = w4 >> 1;
    assign w6 = w5 >> 1;
    assign w7 = w6 >> 1;
    assign w8 = w7 >> 1;
    assign w9 = w8 >> 1;
    assign w10 = w9 >> 1;
    assign w11 = w10 >> 1;
    assign w12 = w11 >> 1;
    assign w13 = w12 >> 1;
    assign w14 = w13 >> 1;
    assign w15 = w14 >> 1;
    assign w16 = w15 >> 1;
    assign w17 = w16 >> 1;
    assign w18 = w17 >> 1;
    assign w19 = w18 >> 1;
    assign w20 = w19 >> 1;
    assign w21 = w20 >> 1;
    assign w22 = w21 >> 1;
    assign w23 = w22 >> 1;

    wire [7:0] h0, h1, h2, h3, h4, h5, h6, h7, h8, h9, h10, h11, h12, h13, h14, h15, h16, h17, h18, h19, h20, h21, h22, h23;

    //Binary Tree control architecture
    wire [7:0] g = {1'b0, w23, h23, h22, h21, h20, h19, h18};
    wire [7:0] a = {1'b0, h0, h1, h2, h3, h4, h5, h6};
    wire [7:0] b = {1'b0, h7, h8, h9, h10, h11, h12, h13};
    wire [7:0] c = {1'b0, h14, h15, h16, h17, h18, h19, h20};

    assign out = (w16 < w23) ? g : a | b | c; // alternating select condition
endmodule

