module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    wire a0, a1, a2, a3, a4, a5, a6, a7;

    wire b0, b1, b2, b3, b4, b5, b6, b7;

    assign out = {a7, a6, a5, a4, a3, a2, a1, a0};

    assign a0 = in[0] & ~shift[0] | in[1] & shift[0] & ~shift[1] | in[2] & shift[0] & shift[1] & ~shift[2] | in[3] & shift[0] & shift[1] & shift[2];
    assign a1 = in[1] & ~shift[0] | in[2] & shift[0] & ~shift[1] | in[3] & shift[0] & shift[1] & ~shift[2] | in[4] & shift[0] & shift[1] & shift[2];
    assign a2 = in[2] & ~shift[0] | in[3] & shift[0] & ~shift[1] | in[4] & shift[0] & shift[1] & ~shift[2] | in[5] & shift[0] & shift[1] & shift[2];
    assign a3 = in[3] & ~shift[0] | in[4] & shift[0] & ~shift[1] | in[5] & shift[0] & shift[1] & ~shift[2] | in[6] & shift[0] & shift[1] & shift[2];
    assign a4 = in[4] & ~shift[0] | in[5] & shift[0] & ~shift[1] | in[6] & shift[0] & shift[1] & ~shift[2] | in[7] & shift[0] & shift[1] & shift[2];
    assign a5 = in[5] & ~shift[0] | in[6] & shift[0] & ~shift[1] | in[7] & shift[0] & shift[1] & ~shift[2];
    assign a6 = in[6] & ~shift[0] | in[7] & shift[0] & ~shift[1];
    assign a7 = in[7] & ~shift[0];

    assign b0 = in[0] & ~shift[1] | in[1] & shift[1] & ~shift[2] | in[2] & shift[1] & shift[2];
    assign b1 = in[1] & ~shift[1] | in[2] & shift[1] & ~shift[2] | in[3] & shift[1] & shift[2];
    assign b2 = in[2] & ~shift[1] | in[3] & shift[1] & ~shift[2] | in[4] & shift[1] & shift[2];
    assign b3 = in[3] & ~shift[1] | in[4] & shift[1] & ~shift[2] | in[5] & shift[1] & shift[2];
    assign b4 = in[4] & ~shift[1] | in[5] & shift[1] & ~shift[2] | in[6] & shift[1] & shift[2];
    assign b5 = in[5] & ~shift[1] | in[6] & shift[1] & ~shift[2] | in[7] & shift[1] & shift[2];
    assign b6 = in[6] & ~shift[1] | in[7] & shift[1];
    assign b7 = in[7] & ~shift[1];

    assign a0 = in[0] & ~shift[0] | in[1] & shift[0] & ~shift[1] | in[2] & shift[0] & shift[1] & ~shift[2] | in[3] & shift[0] & shift[1] & shift[2];
    assign a1 = in[1] & ~shift[0] | in[2] & shift[0] & ~shift[1] | in[3] & shift[0] & shift[1] & ~shift[2] | in[4] & shift[0] & shift[1] & shift[2];
    assign a2 = in[2] & ~shift[0] | in[3] & shift[0] & ~shift[1] | in[4] & shift[0] & shift[1] & ~shift[2] | in[5] & shift[0] & shift[1] & shift[2];
    assign a3 = in[3] & ~shift[0] | in[4] & shift[0] & ~shift[1] | in[5] & shift[0] & shift[1] & ~shift[2] | in[6] & shift[0] & shift[1] & shift[2];
    assign a4 = in[4] & ~shift[0] | in[5] & shift[0] & ~shift[1] | in[6] & shift[0] & shift[1] & ~shift[2] | in[7] & shift[0] & shift[1] & shift[2];
    assign a5 = in[5] & ~shift[0] | in[6] & shift[0] & ~shift[1] | in[7] & shift[0] & shift[1] & ~shift[2];
    assign a6 = in[6] & ~shift[0] | in[7] & shift[0] & ~shift[1];
    assign a7 = in[7] & ~shift[0];

    assign out = {a7, a6, a5, a4, a3, a2, a1, a0};
endmodule

