module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out[0] = data_in[0] ^ (data_in[2] & data_in[4]);
    assign data_out[1] = data_in[1] | data_in[2] & data_in[4];
    assign data_out[2] = data_in[2] & data_in[3];
    assign data_out[3] = data_in[3] ^ data_in[4] | data_in[5];
    assign data_out[4] = data_in[4] & data_in[5] & data_in[6];
    assign data_out[5] = data_in[4] & data_in[6] & data_in[7];
    assign data_out[6] = data_in[5] & data_in[7] | data_in[6] & data_in[7] ^ data_in[5] & data_in[6];
    assign data_out[7] = data_in[6] & data_in[7];
endmodule

