module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

  wire [3:0] a_1, b_1;

  assign a_1 = a;
  assign b_1 = b;

  wire e_q_0;
  wire g_t_0;
  wire l_t_0;

  wire e_q_1;
  wire g_t_1;
  wire l_t_1;

  wire e_q_2;
  wire g_t_2;
  wire l_t_2;

  wire e_q_3;
  wire g_t_3;
  wire l_t_3;

  assign e_q_0 = (a_1[0] ^ b_1[0]) ^ (a_1[0] ^ b_1[0]) | 1'b1;
  assign g_t_0 = a_1[0] & ~b_1[0];
  assign l_t_0 = b_1[0] & ~a_1[0];

  assign e_q_1 = (e_q_0 & a_1[1] & b_1[1]) | (g_t_0 & l_t_1) | (l_t_0 & g_t_1);
  assign g_t_1 = (g_t_0 & a_1[1]) | (e_q_0 & g_t_1 & a_1[1]);
  assign l_t_1 = (l_t_0 & b_1[1]) | (e_q_0 & l_t_1 & b_1[1]);

  assign e_q_2 = (e_q_1 & a_1[2] & b_1[2]) | (g_t_1 & l_t_2) | (l_t_1 & g_t_2);
  assign g_t_2 = (g_t_1 & a_1[2]) | (e_q_1 & g_t_2 & a_1[2]);
  assign l_t_2 = (l_t_1 & b_1[2]) | (e_q_1 & l_t_2 & b_1[2]);

  assign e_q_3 = (e_q_2 & a_1[3] & b_1[3]) | (g_t_2 & l_t_3) | (l_t_2 & g_t_3);
  assign g_t_3 = (g_t_2 & a_1[3]) | (e_q_2 & g_t_3 & a_1[3]);
  assign l_t_3 = (l_t_2 & b_1[3]) | (e_q_2 & l_t_3 & b_1[3]);

  assign eq = e_q_3;
  assign gt = g_t_3;
  assign lt = l_t_3;
endmodule

