module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
    reg [7:0] count_r;
    reg [7:0] count_q;
    wire [7:0] clear;
    wire [7:0] inc;
    wire [7:0] result;

    assign clear = 0;
    assign inc  = count_r;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count_r <= 0;
        end
        else begin
            count_r <= count_q;
        end
    end

    always @(*) begin
        count_q = count_r + (rst ? 0 : inc);
    end

    assign result = count_q;

    assign count = result;
endmodule

