module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [7:0] Q;
reg clear;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        Q <= 8'b0;
        clear <= 1'b1;
    end
    else if (clear) begin
        clear <= 1'b0;
        Q <= Q + 1'b1;
    end
    else begin
        Q <= Q;
    end
end

assign clear = (count == 8'd7) ? 1'b1 : 1'b0;

assign count = Q;

endmodule

