module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);

reg S;
reg D;
reg E;
reg C;

always @ (posedge clk) begin
  if (!R) begin
    S <= w;
  end else if (E) begin
    S <= 1'b0;
  end
end

always @ (posedge clk) begin
  if (S) begin
    if (!E) begin
      Q <= 0;
    end else begin
      if (C) begin
        if (L) begin
          D <= 1'b1;
        end else begin
          D <= 1'b0;
        end
      end
